/* Bolt update: flies on, sparks out at the end of its range, bursts on impact, removes it out of bounds. Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/l07/gameplay/entities/002cd2b0.c, FUN_L07_0030b6a8. */
void update_linear_projectile(Moby *m) {
    BoltVars_30CA88 *v = (BoltVars_30CA88 *)((void *)m->pvars);
    Vec4 old;
    Vec4 dir;
    Vec4 spark;
    int pass;
    int i;
    int j;

    qcopy(&old, &m->pos);
    FastVecAdd(&m->pos, &m->pos, &v->vel);
    pass = v->solid == 0;
    if (vec_distance_xy(&m->pos, &v->origin) > 30.0f) {
        if (m->visible != 0) {
            for (i = 0; i < 3; i++) {
                spark.q = 0;
                spark.f[0] = random_float_between(-1.0f, 1.0f);
                spark.f[1] = random_float_between(-1.0f, 1.0f);
                spark.f[2] = random_float_between(-1.0f, 1.0f);
                dir.q = spark.q;
                vec_scale_to_length(&dir, &dir, FastVecLength(&spark) * 0.1f);
                FastVecAdd(&dir, &spark, &dir);
                vec_scale_to_length(&dir, &dir,
                                  random_float_between(g_frame_time + g_frame_time, g_frame_time * 4.0f));
                spawn_projectile_expiry_particle_r(&m->pos, &dir);
            }
        }
        DeleteMoby(m);
        return;
    }
    if ((m->visible != 0 || vec_distance_xy(&m->pos, hero_globals_base + 0xE9D) < 30.0f) &&
        coll_line_r(&old, &m->pos, pass, v->ignore, v) != 0) {
        qcopy(&m->pos, &umbris_coll_hit_point);
        if (m->visible != 0) {
            for (j = 0; j < 5; j++) {
                spark.q = 0;
                spark.f[0] = random_float_between(-1.0f, 1.0f);
                spark.f[1] = random_float_between(-1.0f, 1.0f);
                spark.f[2] = random_float_between(-1.0f, 1.0f);
                dir.q = spark.q;
                vec_reflect(&spark, &v->vel, umbris_coll_hit_normal);
                vec_scale_to_length(&dir, &dir, FastVecLength(&spark) * 0.5f);
                FastVecAdd(&dir, &spark, &dir);
                vec_scale_to_length(&dir, &dir,
                                  random_float_between(g_frame_time * 3.0f, g_frame_time * 6.0f));
                PartType27Spawn((char *)&m->pos, (char *)&dir, 0x7F2F4F6F,
                                  rand_range(scale_ticks(10), scale_ticks(15)),
                                  30000.0f);
            }
        }
        Moby_PlaySound_r(0, 0, m);
        DeleteMoby(m);
        return;
    }
    if (m->pos.x < 2.0f || m->pos.x > 1021.0f || m->pos.y < 2.0f || m->pos.y > 1021.0f ||
        m->pos.z < 2.0f || m->pos.z > 1021.0f) {
        DeleteMoby(m);
    }
}
