/* Debris update: moves and spins it, bursts it on impact, removes it out of bounds.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l07/gameplay/entities/002cd2b0.c, FUN_L07_0030bbc8. */
void update_tumbling_ballistic_moby(struct Moby *m) {
    Vec4f *pos = &m->pos;
    DebrisVars_0CFA8 *d = (DebrisVars_0CFA8 *)m->pvars;
    Vec4 old;
    float size;

    qcopy(&old, pos);
    FastVecAdd(pos, pos, d);
    d->vel.z -= g_frame_time_sq * 9.8f;
    m->rot.y = FastAddRots(m->rot.y, d->spin_y);
    m->rot.z = FastAddRots(m->rot.z, d->spin_z);
    if (coll_line_r2(&old, pos, 0, d->ignore, 0) != 0 || coll_sphere(0.5f, pos, 0, d->ignore) != 0) {
        if (debris_target_r == 0 || (u16)(debris_target_r->oclass - 0x371) >= 2) {
            if (m->visible != 0 || vec_distance_xy(pos, gHeroPos) < 5.0f) {
                size = 0.0f;
                if (d->variant % 3 == 0) {
                    size = 10.0f;
                }
                if (vec_distance_xy(pos, debris_far_point) > 50.0f) {
                    if (d->variant & 1) {
                        spawn_explosion(m, d, 0, 2.0f, 1.0f, 1, 2, 3, 0.0f, 0.0f, 1000.0f, 1.3f, -1,
                                        size, 0, 1, -1, 0);
                    } else {
                        spawn_explosion(m, d, 0, 2.0f, 1.0f, 0, 2, 3, 0.0f, 0.0f, 1000.0f, 1.2f, 0,
                                        size, 0, 1, -1, 0);
                    }
                } else {
                    if (d->variant & 1) {
                        spawn_explosion(m, d, 0, 2.0f, 1.0f, 0, 2, 4, 0.0f, 1.0f, 1000.0f, 1.0f, 0,
                                        size, 0, 1, -1, 0);
                    } else {
                        spawn_explosion(m, d, 0, 2.0f, 1.0f, 1, 2, 4, 0.0f, 0.0f, 1000.0f, 1.0f, 0,
                                        size, 0, 1, -1, 0);
                    }
                }
            } else {
                Moby_PlaySound_r2(0, 0, m);
            }
            DeleteMoby(m);
            return;
        }
    }
    if (m->pos.x < 2.0f || m->pos.x > 1021.0f || m->pos.y < 2.0f || m->pos.y > 1021.0f ||
        m->pos.z < 2.0f || m->pos.z > 1021.0f) {
        DeleteMoby(m);
    }
}
