    AddDrawCallback((void *)draw_fading_ring_effect, m);
    register_fading_ring_hit(*(void **)(hero_globals_base + 0x2E9D), m, d);
    for (p = umbris_moby_list; p; p = *(char **)(p + 0x28)) {
        register_fading_ring_hit(p, m, d);
    }
